#include <iostream>
#include <string>

int main()
{
    std::string word{};
    std::string longest{};
    int count{};

    while (std::cin >> word)
    {
        ++count;
        if (word.size() > longest.size()) longest = word;
    }

    std::cout << "words " << count << "\n";

    if (count == 0)
    {
        std::cout << "longest none\n";
        std::cout << "letters 0\n";
    }
    else
    {
        std::cout << "longest " << longest << "\n";
        std::cout << "letters " << longest.size() << "\n";
    }

    return 0;
}
